function tileShuffle(board) {
  const moves = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]];
  const goal = '123450';
  const dfs = (s, depth, from) => {
    if (s === goal) return true;
    if (depth === 0) return false;
    const z = s.indexOf('0');
    for (const m of moves[z]) {
      if (m === from) continue;
      const t = [...s];
      [t[z], t[m]] = [t[m], t[z]];
      if (dfs(t.join(''), depth - 1, z)) return true;
    }
    return false;
  };
  const start = [...board[0], ...board[1]].join('');
  for (let limit = 0; limit <= 21; limit++) if (dfs(start, limit, -1)) return limit;
  return -1;
}

