function tileShuffle(board) {
  const moves = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]];
  const goal = '123450';
  const start = [...board[0], ...board[1]].join('');
  const seen = new Set([start]);
  let layer = [start];
  for (let steps = 0; layer.length; steps++) {
    const next = [];
    for (const s of layer) {
      if (s === goal) return steps;
      const z = s.indexOf('0');
      for (const m of moves[z]) {
        const t = [...s];
        [t[z], t[m]] = [t[m], t[z]];
        const key = t.join('');
        if (!seen.has(key)) { seen.add(key); next.push(key); }
      }
    }
    layer = next;
  }
  return -1;
}
